// Validate the uploaded file (multipart field "file"). Throwing sends it to the error branch.
const upload = $('Webhook: invoice file').first();
const file = (upload.binary || {}).file;
if (!file) throw new Error('no file uploaded (send it as the multipart field "file")');
const fileName = file.fileName || 'unknown';
const extension = (fileName.split('.').pop() || '').toLowerCase();
if (!['pdf', 'txt'].includes(extension)) throw new Error(`unsupported file type .${extension}`);
const runTag = (upload.json.body || {}).run_tag || '';
// step tells the error branch what failed if text extraction breaks (e.g. a corrupt PDF)
return [{ json: { file_name: fileName, is_pdf: extension === 'pdf', run_tag: runTag, step: 'extract_text' }, binary: upload.binary }];

// Idempotency: the same input twice must not create two records.
// Keys live in this workflow's static data (n8n saves it after production runs, not manual test runs).
const item = $input.first().json;
const key = `${item.run_tag}|file|${item.file_hash}`;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const duplicate = Boolean(store.seen[key]);
if (!duplicate) store.seen[key] = new Date().toISOString();
const json = { ...item, dedupe_key: key, is_duplicate: duplicate };
const binary = $('Check file').first().binary; // invoices carry the uploaded file along
return [binary ? { json, binary } : { json }];

// Build the extraction request from the text of the file (PDF or .txt branch).
const cfg = $('Config').first().json;
const seen = $('Seen before?').first().json;
const text = String($input.first().json.text || '');
return [{
  json: {
    file_name: seen.file_name,
    run_tag: seen.run_tag,
    dedupe_key: seen.dedupe_key,
    has_text: text.trim().length > 0,
    step: 'ai_extract',
    llm_request: {
      model: cfg.model_cheap,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [{ role: 'system', content: cfg.prompt_extract }, { role: 'user', content: JSON.stringify({ file_name: seen.file_name, text }) }],
    },
  },
}];

// JSON-schema check of the model's reply. Invalid output is never used: it goes to human review.
// Parse the model's reply and check it against a JSON Schema (the subset our schemas use).
function parseJsonObject(text) {
  if (!text) return null;
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try {
    const value = JSON.parse(text.slice(start, end + 1));
    return value && typeof value === 'object' && !Array.isArray(value) ? value : null;
  } catch (error) {
    return null;
  }
}
function isType(value, type) {
  if (type === 'null') return value === null;
  if (type === 'number') return typeof value === 'number' && Number.isFinite(value);
  if (type === 'integer') return Number.isInteger(value);
  if (type === 'object') return value !== null && typeof value === 'object' && !Array.isArray(value);
  if (type === 'array') return Array.isArray(value);
  return typeof value === type;
}
function schemaErrors(value, schema, path = '$') {
  if (value === null && path === '$') return ['output is not a JSON object'];
  const types = [].concat(schema.type || []);
  if (types.length && !types.some((type) => isType(value, type))) return [`${path}: expected ${types.join(' or ')}`];
  const errors = [];
  if (schema.enum && !schema.enum.includes(value)) errors.push(`${path}: must be one of ${JSON.stringify(schema.enum)}`);
  if (typeof value === 'number') {
    if (schema.minimum !== undefined && value < schema.minimum) errors.push(`${path}: below ${schema.minimum}`);
    if (schema.maximum !== undefined && value > schema.maximum) errors.push(`${path}: above ${schema.maximum}`);
  }
  if (typeof value === 'string') {
    if (schema.maxLength !== undefined && value.length > schema.maxLength) errors.push(`${path}: longer than ${schema.maxLength}`);
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) errors.push(`${path}: does not match ${schema.pattern}`);
  }
  if (isType(value, 'object')) {
    const properties = schema.properties || {};
    for (const key of schema.required || []) if (!(key in value)) errors.push(`${path}.${key}: missing`);
    for (const [key, sub] of Object.entries(properties)) if (key in value) errors.push(...schemaErrors(value[key], sub, `${path}.${key}`));
    if (schema.additionalProperties === false) {
      for (const key of Object.keys(value)) if (!(key in properties)) errors.push(`${path}.${key}: not allowed`);
    }
  }
  return errors;
}
const SCHEMA = {"$schema": "https://json-schema.org/draft/2020-12/schema", "title": "Invoice fields", "type": "object", "required": ["supplier_name", "invoice_number", "invoice_date", "currency", "net_amount", "vat_rate", "vat_amount", "total_amount", "confidence"], "additionalProperties": false, "properties": {"supplier_name": {"type": ["string", "null"], "maxLength": 160}, "invoice_number": {"type": ["string", "null"], "maxLength": 60}, "invoice_date": {"type": ["string", "null"], "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}, "currency": {"type": ["string", "null"], "enum": ["AED", "EUR", "GBP", "USD", null]}, "net_amount": {"type": ["number", "null"], "minimum": 0}, "vat_rate": {"type": ["number", "null"], "minimum": 0, "maximum": 30}, "vat_amount": {"type": ["number", "null"], "minimum": 0}, "total_amount": {"type": ["number", "null"], "minimum": 0}, "confidence": {"type": "number", "minimum": 0, "maximum": 1}}};
const { llm_request, ...context } = $('Build AI request').first().json;
const content = $input.first().json.choices?.[0]?.message?.content || '';
const ai = parseJsonObject(content);
const errors = schemaErrors(ai, SCHEMA);
return [{ json: { ...context, ai: errors.length ? null : ai, schema_errors: errors } }];

// The money checks are done in code, never by the AI:
// total = net + VAT, VAT = net x rate, a known VAT rate, no missing field, confidence high enough,
// and the same supplier + invoice number is never booked twice.
const FIELDS = ["supplier_name", "invoice_number", "invoice_date", "currency", "net_amount", "vat_rate", "vat_amount", "total_amount"];
const KNOWN_VAT_RATES = {"AED": [5.0, 0.0], "GBP": [20.0, 5.0, 0.0], "EUR": [20.0, 10.0, 5.5, 0.0], "USD": [0.0]};
const cfg = $('Config').first().json;
const item = $input.first().json;
const tolerance = Number(cfg.money_tolerance) + 1e-9; // tiny extra margin for floating-point noise
const present = (v) => v !== null && v !== undefined && v !== '';
const normalise = (s) => String(s || '').trim().toLowerCase().replace(/\s+/g, ' ');

function validateFields(f) {
  const issues = FIELDS.filter((name) => !present(f[name])).map((name) => `missing ${name}`);
  const { net_amount: net, vat_amount: vat, total_amount: total, vat_rate: rate, currency } = f;
  if ([net, vat, total].every(present) && Math.abs(net + vat - total) > tolerance) issues.push('total does not equal net + VAT');
  if ([net, vat, rate].every(present) && Math.abs((net * rate) / 100 - vat) > tolerance) issues.push('VAT amount does not equal net x rate');
  if (present(rate) && KNOWN_VAT_RATES[currency] && !KNOWN_VAT_RATES[currency].includes(Number(rate))) issues.push(`unusual VAT rate ${rate}% for ${currency}`);
  return issues;
}

function decide(f, runTag) {
  if (f === null) return { status: 'needs_review', reasons: ['AI output failed the JSON schema check'] };
  const issues = validateFields(f);
  if (f.confidence < Number(cfg.invoice_min_confidence)) issues.push('low confidence');
  const supplier = normalise(f.supplier_name);
  const number = normalise(f.invoice_number);
  const key = supplier && number ? `${runTag}|invoice|${supplier}|${number}` : null;
  const store = $getWorkflowStaticData('global');
  store.booked = store.booked || {};
  if (key && store.booked[key]) return { status: 'duplicate', reasons: ['invoice number already booked for this supplier'] };
  if (issues.length) return { status: 'needs_review', reasons: issues };
  store.booked[key] = new Date().toISOString(); // only booked invoices are remembered
  return { status: 'accepted', reasons: [] };
}

const fields = item.ai ? Object.fromEntries([...FIELDS, 'confidence'].map((k) => [k, item.ai[k]])) : {};
return [{ json: { file_name: item.file_name, ...decide(item.ai, item.run_tag), fields } }];

// Invoice register row (every file) + the shared human-check queue for anything doubtful.
// Reached from "Check totals & VAT", or directly when no text was found in the file.
// CSV helpers: one line per record, quoted only when needed (same rule as Python's csv module).
function csvCell(value) {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  return /[",\n\r]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}
function csvRow(columns, record) {
  return columns.map((column) => csvCell(record[column])).join(',') + '\n';
}
const REGISTER_COLUMNS = ["timestamp", "file_name", "status", "reasons", "supplier_name", "invoice_number", "invoice_date", "currency", "net_amount", "vat_rate", "vat_amount", "total_amount", "confidence"];
const REVIEW_COLUMNS = ["timestamp", "workflow", "item_id", "reason", "details"];
const cfg = $('Config').first().json;
const incoming = $input.first().json;
const r = incoming.status ? incoming : { file_name: incoming.file_name, status: 'needs_review', reasons: ['no text found (scanned image? needs OCR)'], fields: {} };
const now = new Date().toISOString();
const reasons = r.reasons.join('; ');
const rows = [{ target_path: `${cfg.base_dir}/outputs/invoice_register.csv`, line: csvRow(REGISTER_COLUMNS, { ...r.fields, ...r, timestamp: now, reasons }) }];
if (r.status === 'needs_review') {
  const review = { timestamp: now, workflow: 'invoice_extraction', item_id: r.file_name, reason: reasons, details: r.fields };
  rows.push({ target_path: `${cfg.base_dir}/outputs/human_review_queue.csv`, line: csvRow(REVIEW_COLUMNS, review) });
}
const response = { file_name: r.file_name, status: r.status, reasons: r.reasons, fields: r.fields };
return rows.map((row) => ({ json: { ...row, response } }));

// Error branch: write one row to logs/errors.csv, forget the idempotency key so the input
// can be retried later, and answer the webhook caller with status "error".
// CSV helpers: one line per record, quoted only when needed (same rule as Python's csv module).
function csvCell(value) {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  return /[",\n\r]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}
function csvRow(columns, record) {
  return columns.map((column) => csvCell(record[column])).join(',') + '\n';
}
const COLUMNS = ["timestamp", "workflow", "item_id", "step", "error_type", "message"];
const cfg = $('Config').first().json;
const item = $input.first().json;
const error = item.error || 'unknown error';
const message = typeof error === 'string' ? error : error.description || error.message || JSON.stringify(error);
let itemId = 'unknown';
try {
  itemId = $('Webhook: invoice file').first().binary.file.fileName || itemId; // straight from the trigger, in case the input check failed
} catch (noTrigger) {
  // started by the schedule, or no such field
}
try {
  const checked = $('Seen before?').first().json;
  itemId = checked.file_name || itemId;
  const key = checked.dedupe_key || checked.dedupe_text;
  const store = $getWorkflowStaticData('global');
  if (key && store.seen) delete store.seen[key];
} catch (notExecuted) {
  // the input check itself failed, so no key was stored yet
}
const record = {
  timestamp: new Date().toISOString(),
  workflow: 'invoice_extraction',
  item_id: itemId,
  step: item.step || 'check_input',
  error_type: typeof error === 'string' ? 'Error' : error.name || 'Error',
  message: String(message).slice(0, 500),
};
return [{
  json: {
    target_path: `${cfg.base_dir}/logs/errors.csv`,
    line: csvRow(COLUMNS, record),
    response: { status: 'error', item_id: itemId, step: record.step, reason: record.message },
  },
}];
